select * from eventsalesitem order by createdat desc
SELECT a.OrderId,a.SalesOrderCode, a.SalesOrderTotal, a.CustomerId,a.EventId,a.SalesTax,a.CreatedAt,
                            a.PaymentIntentId,a.StripeSessionId, b.StripeAccountId, c.EventName
                            FROM salesorder a
                            inner join eventorganizer b on a.CustomerId=b.CustomerId
                            inner join Events c on a.EventId=c.EventId
                            WHERE a.CreatedAt >= DATE_SUB(UTC_TIMESTAMP(), INTERVAL 1000 HOUR)
                         
                           
                            AND a.SalesOrderStatus=7
                            ORDER BY CreatedAt DESC
                            
